package com.bank.reward.service;

import java.util.logging.Logger;

// Counts ordered ways to form a target using steps of 1, 3, and 4.
public class RewardPathService {
    private static final Logger log = Logger.getLogger(RewardPathService.class.getName());

    public long countWays(int target) {
        long[] dp = new long[target + 1];
        dp[0] = 1;                                  // one way: empty sum
        for (int i = 1; i <= target; i++) {
            if (i >= 1) dp[i] += dp[i - 1];         // last step was 1
            if (i >= 3) dp[i] += dp[i - 3];         // last step was 3
            if (i >= 4) dp[i] += dp[i - 4];         // last step was 4
        }
        log.info(() -> "Ordered ways to form " + target + " = " + dp[target]);
        return dp[target];
    }
}
