package com.bank.reward;

import com.bank.reward.service.RewardPathService;
import java.util.logging.Logger;

public class RewardPathApplication {
    private static final Logger log = Logger.getLogger(RewardPathApplication.class.getName());

    public static void main(String[] args) {
        RewardPathService service = new RewardPathService();
        int target = 5;
        long ways = service.countWays(target);
        log.info("Ordered ways to reach reward target " + target + ": " + ways);
    }
}
